$(document).ready(function(){
    if($(document).outerWidth() < 1025){
        var slider = $('.buttons__constructions');
        slider.owlCarousel({
            items: 1,
            loop: false,
            nav: true,
            dots: false,
            center: false,
            lazyLoad: false,
            smartSpeed: 1e3,
            URLhashListener: false,
            autoplay: false
        })
        slider.on('changed.owl.carousel', function(event) {
            setTimeout(function(){
                var currentSlide = slider.find('.button__constructions.active');
                var countSlide = $('.owl-item.active').index() + 1;

                $('.button__constructions').removeClass('active');
                $('.owl-item.active').find('.button__constructions').addClass('active');

                $('.tab__constructions-text').removeClass('active');
                $('.tab__constructions-text:nth-child('+ countSlide +')').addClass('active');
            }, 300)
        })
    }

    $('.mobile-button').on('click', function(e){
        e.preventDefault();
        $('main').toggleClass('open');
        $('footer').toggleClass('open');
        $('.header').toggleClass('active');
    });

    /*$('.menu__arrow a').on('click', function() {
        if($(this).closest('.menu__item').hasClass('opened')){
            $('.menu__item').removeClass('opened').find('.sub-menu__wrap').stop().slideUp('0');
        }else{
            $('.menu__item').removeClass('opened').find('.sub-menu__wrap').stop().slideUp('0');
            $(this).closest('.menu__item').addClass('opened').find('.sub-menu__wrap').stop().slideDown('0');
        }
    })

    $(window).resize(function(){
        if($(window).outerWidth() > 1150){
            $('.sub-menu__wrap').removeAttr("style");
            $('.menu__item').removeClass('opened');
        }
    })


    var roadmapAnimation = function() {
        if($('.about__history').hasClass('lock')){
            var scrollPath = $('.history-scroll-bottom').outerWidth() - $(document).width() + 52;
            console.log(scrollPath +'__'+ $('.history-scroll-bottom').outerWidth() + '__' +$(document).width())
            var scrollSpeed = 24000 - ($(document).outerWidth() * 6);

            $('.about__history-scroll').animate({                    
                scrollLeft: scrollPath
            }, scrollSpeed, 'linear', function(){
                setTimeout(function(){
                    $('.about__history').removeClass('lock')
                    $('.about__history-scroll').stop();
                }, 600)

                $('.about__history-scroll').on('mousewheel DOMMouseScroll', function(event){
                    var delta = Math.max(-1, Math.min(1, (event.originalEvent.wheelDelta || -event.originalEvent.detail)));
                    $(this).scrollLeft( $(this).scrollLeft() - ( delta * 40 ) );
                    event.preventDefault();
                });
            });
        }else{
            $('.about__history-scroll').stop();
        }
    }
    $(document).scroll(function(){
        if($(document).scrollTop() > ($('.about__history').offset().top - ($('.about__history').outerHeight()/2)) ){
            //roadmapAnimation();
        }
    })
/*
    $('.about__history-scroll').on('mousewheel DOMMouseScroll', function(event){
        var delta = Math.max(-1, Math.min(1, (event.originalEvent.wheelDelta || -event.originalEvent.detail)));
        $(this).scrollLeft( $(this).scrollLeft() - ( delta * 40 ) );
        event.preventDefault();
    });
*/

    if ($('.about__history-scroll').length) {
        const hiSlider = document.querySelector('.about__history-scroll');
        let isDown = false;
        let startX;
        let scrollLeft;

        hiSlider.addEventListener('mousedown', (e) => {
            isDown = true;
            hiSlider.classList.add('active');
            startX = e.pageX - hiSlider.offsetLeft;
            scrollLeft = hiSlider.scrollLeft;
        });
        hiSlider.addEventListener('mouseleave', () => {
            isDown = false;
            hiSlider.classList.remove('active');
        });
        hiSlider.addEventListener('mouseup', () => {
            isDown = false;
            hiSlider.classList.remove('active');
        });
        hiSlider.addEventListener('mousemove', (e) => {
            if(!isDown) return;
            e.preventDefault();
            const x = e.pageX - hiSlider.offsetLeft;
            const walk = (x - startX) * 1; //scroll-fast
            hiSlider.scrollLeft = scrollLeft - walk;
        });
    }

    $('.constructions__big-image.construct').slick({
        arrows: false,
        dots: false,
        infinite: true,
        speed: 300,
        slidesToShow: 1,
        slidesToScroll: 1,
        asNavFor: '.constructions__mini-image.construct'
    });

    $('.constructions__mini-image.construct').slick({
        arrows: true,
        prevArrow: '<a href="#" class="constructions__arrow slick-prev"><svg width="21" height="8" viewBox="0 0 21 8" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M0.646446 4.35355C0.451183 4.15829 0.451183 3.84171 0.646446 3.64645L3.82843 0.464466C4.02369 0.269204 4.34027 0.269204 4.53553 0.464466C4.73079 0.659728 4.73079 0.976311 4.53553 1.17157L1.70711 4L4.53553 6.82843C4.73079 7.02369 4.73079 7.34027 4.53553 7.53553C4.34027 7.7308 4.02369 7.7308 3.82843 7.53553L0.646446 4.35355ZM21 4.5H1V3.5H21V4.5Z" fill="black"/></svg>\n</a>',
        nextArrow: '<a href="#" class="constructions__arrow slick-next"><svg width="21" height="8" viewBox="0 0 21 8" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M0.646446 4.35355C0.451183 4.15829 0.451183 3.84171 0.646446 3.64645L3.82843 0.464466C4.02369 0.269204 4.34027 0.269204 4.53553 0.464466C4.73079 0.659728 4.73079 0.976311 4.53553 1.17157L1.70711 4L4.53553 6.82843C4.73079 7.02369 4.73079 7.34027 4.53553 7.53553C4.34027 7.7308 4.02369 7.7308 3.82843 7.53553L0.646446 4.35355ZM21 4.5H1V3.5H21V4.5Z" fill="black"/></svg>\n</a>',
        dots: false,
        infinite: true,
        speed: 300,
        slidesToShow: 2,
        slidesToScroll: 1,
        asNavFor: '.constructions__big-image.construct'
    });

    $('.constructions__mini-image.section__catalog img').click(function () {
        let src = $(this).attr('src');
        $(this).parents('.constructions__images-block').find('.constructions__big-image').find('img').attr('src', src);
    });
    
    if ($('.constructions__tabs .block__constructions-tabs .tabs__constructions .tab__constructions-text .constructions__images-block .constructions__mini-image img').length <= 7) {
        $('.constructions__tabs .block__constructions-tabs .tabs__constructions .tab__constructions-text .constructions__images-block .constructions__mini-image').hide();
    }
});

$(window).on('load', function () {
    $('.search__result__count').insertAfter($('.search-page h1'));
});

$(window).on('load resize', function () {
    if ($(window).width() < 1151) {
        $('.header__menu .menu__item:nth-child(2) .sub-menu li div > a').unbind("click");
        $('.header__menu .menu__item:nth-child(2) .sub-menu li div > a').click(function (e) {
            e.preventDefault();
            $(this).parent('div').parent('li').find('.block-menu').fadeToggle();
            // console.log($(this).parents('li').find('.block-menu'));
            return false;
        });
    }
});


if($(document).outerWidth() > 1279) {
        $('.header nav .header__menu .menu__item').mouseenter(function(event) {
            $(this).toggleClass('active');
        });

        $('.header nav .header__menu .menu__item').mouseleave(function(event) {
            $(this).toggleClass('active');
        });
}
else {
    $('.header nav .header__menu .menu__item:nth-child(1)').click(function(event) {
        $(this).toggleClass('active');
        $('.header nav .header__menu .menu__item:nth-child(2)').removeClass('active');
        $('.header nav .header__menu .menu__item:nth-child(3)').removeClass('active');
    });


    $('.header nav .header__menu .menu__item:nth-child(2)').click(function(event) {
        $(this).toggleClass('active');
        $('.header nav .header__menu .menu__item:nth-child(1)').removeClass('active');
        $('.header nav .header__menu .menu__item:nth-child(3)').removeClass('active');
    });

    $('.header nav .header__menu .menu__item:nth-child(3)').click(function(event) {
        $(this).toggleClass('active');
        $('.header nav .header__menu .menu__item:nth-child(1)').removeClass('active');
        $('.header nav .header__menu .menu__item:nth-child(2)').removeClass('active');
    });

}

